const page=document.body.dataset.page||'inicio';
const wa='https://wa.me/5519981744852?text=Ol%C3%A1%21%20Conheci%20o%20trabalho%20da%20DLD%20pelo%20site%20e%20gostaria%20de%20solicitar%20uma%20proposta.';
const nav=[['inicio','index.html','Início'],['sobre','sobre.html','Sobre'],['servicos','servicos.html','Serviços'],['projetos','projetos.html','Projetos'],['portfolio','portfolio.html','Trabalhos'],['fotos','fotos.html','Fotos'],['parceiros','parceiros.html','Parceiros'],['contato','contato.html','Contato']];
const header=`<header class="site-header"><div class="header-inner"><a class="brand" href="index.html"><img src="assets/logo-horizontal-oficial.png" alt="DLD — Du Locuções Divulgações"></a><button class="menu-toggle" aria-label="Abrir menu" aria-expanded="false"><span></span><span></span><span></span></button><nav class="main-nav">${nav.map(([k,u,l])=>`<a class="${page===k?'active':''}" href="${u}">${l}</a>`).join('')}<a class="button button-red header-cta" href="${wa}" target="_blank" rel="noopener">Solicite uma proposta</a></nav><a class="header-monogram" href="index.html"><img src="assets/dld-marca-canto.png" alt="DLD"></a></div></header>`;
const footer=`<footer class="site-footer"><div class="footer-actions-space" aria-hidden="true"></div><div class="footer-inner"><div class="footer-brand-lockup"><img class="footer-logo" src="assets/logo-rodape-oficial.png" alt="DLD — Du Locuções Divulgações — Soluções criativas em comunicação"></div><div class="footer-contact"><a href="${wa}" target="_blank" rel="noopener">WhatsApp: (19) 98174-4852</a><a href="mailto:dulocutor.divulgacoes@yahoo.com">dulocutor.divulgacoes@yahoo.com</a><a href="mailto:dulocucoesdivulgacoes@gmail.com">dulocucoesdivulgacoes@gmail.com</a><a href="https://www.instagram.com/eduardoalvesilva86/" target="_blank" rel="noopener">Instagram</a><a href="https://www.tiktok.com/@dlddulocucoesdivulgacoes?is_from_webapp=1&sender_device=pc" target="_blank" rel="noopener">TikTok</a><a href="https://www.youtube.com/@canaldulocucoesdivulgacoes" target="_blank" rel="noopener">YouTube</a><span>Americana — SP</span></div><img class="footer-signature" src="assets/assinatura-rodape.png" alt="Eduardo Alves da Silva — DLD Du Locuções Divulgações — Brasil"></div><div class="footer-bottom"><span>© 2026 DLD — Du Locuções Divulgações.</span><span>Todos os direitos reservados.</span></div><div class="floating-actions"><a class="float-button" href="https://www.youtube.com/@canaldulocucoesdivulgacoes" target="_blank" rel="noopener" aria-label="YouTube"><svg viewBox="0 0 24 24"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.5 3.6 12 3.6 12 3.6s-7.5 0-9.4.5A3 3 0 0 0 .5 6.2 31 31 0 0 0 0 12a31 31 0 0 0 .5 5.8 3 3 0 0 0 2.1 2.1c1.9.5 9.4.5 9.4.5s7.5 0 9.4-.5a3 3 0 0 0 2.1-2.1A31 31 0 0 0 24 12a31 31 0 0 0-.5-5.8ZM9.6 15.6V8.4l6.3 3.6-6.3 3.6Z"/></svg></a><a class="float-button" href="${wa}" target="_blank" rel="noopener" aria-label="WhatsApp"><svg viewBox="0 0 24 24"><path d="M12 2a9.8 9.8 0 0 0-8.4 14.9L2.2 22l5.2-1.4A10 10 0 1 0 12 2Zm0 18.2a8.2 8.2 0 0 1-4.2-1.1l-.3-.2-3.1.8.8-3-.2-.3A8.2 8.2 0 1 1 12 20.2Zm4.5-6.1c-.3-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1l-.8 1c-.1.2-.3.2-.6.1a6.7 6.7 0 0 1-3.3-2.9c-.2-.3 0-.5.1-.6l.5-.6.2-.5c.1-.2 0-.4 0-.5l-.8-1.8c-.2-.5-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.4-.3.3-1 1-1 2.4s1 2.8 1.2 3c.1.2 2 3.1 4.9 4.3.7.3 1.2.5 1.6.6.7.2 1.3.2 1.8.1.6-.1 1.5-.6 1.7-1.2.2-.6.2-1.1.2-1.2-.1-.2-.3-.3-.5-.4Z"/></svg></a></div></footer>`;
const hs=document.querySelector('[data-shell="header"]');if(hs){hs.insertAdjacentHTML('afterend',header);hs.remove()}
const fs=document.querySelector('[data-shell="footer"]');if(fs){fs.insertAdjacentHTML('afterend',footer);fs.remove()}
document.getElementById('year')?.replaceChildren(String(new Date().getFullYear()));
const toggle=document.querySelector('.menu-toggle'),menu=document.querySelector('.main-nav');toggle?.addEventListener('click',()=>{const o=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(o))});
const pg=document.querySelector('[data-project-gallery]'),lg=document.querySelector('[data-partner-grid]');
if(pg||lg||document.querySelector('[data-gallery-era]'))fetch('assets/content.json').then(r=>r.json()).then(data=>{if(pg)pg.innerHTML=data.projects.map((n,i)=>`<figure class="project-poster"><img src="assets/projects/${encodeURIComponent(n)}" alt="Projeto DLD ${i+1}" loading="lazy"></figure>`).join('');if(lg){lg.innerHTML=data.partners.map(n=>`<figure class="partner-logo"><img src="assets/partners-display/${encodeURIComponent(n)}" alt="${n.replace(/^(Logo|Logos)\s+/i,'').replace(/\.(png|webp)$/i,'')}" loading="lazy"></figure>`).join('');lg.querySelectorAll('img').forEach(img=>{const classify=()=>{const ratio=img.naturalWidth/img.naturalHeight;img.classList.add(ratio>3?'logo-ultrawide':ratio>1.65?'logo-wide':ratio<.78?'logo-tall':'logo-balanced');const area=16500;const visualW=Math.max(110,Math.min(195,Math.sqrt(area*ratio)));const visualH=Math.max(72,Math.min(130,Math.sqrt(area/ratio)));img.style.setProperty('--visual-w',visualW+'px');img.style.setProperty('--visual-h',visualH+'px');if(/Logo PG\.webp$/i.test(decodeURIComponent(img.getAttribute('src')||'')))img.classList.add('logo-paguemenos')};img.complete?classify():img.addEventListener('load',classify,{once:true})})}document.querySelectorAll('[data-gallery-era]').forEach(grid=>{const files=grid.dataset.galleryEra==='all'?['early','expansion','current'].flatMap(era=>(data.gallery&&data.gallery[era])||[]):((data.gallery&&data.gallery[grid.dataset.galleryEra])||[]);grid.innerHTML=files.map((n,i)=>`<figure><button class="photo-open" type="button" aria-label="Ampliar foto ${i+1}"><img src="assets/gallery/${encodeURIComponent(n)}" alt="Trabalho da DLD ${i+1}" loading="${grid.dataset.galleryEra==='early'&&i<6?'eager':'lazy'}"></button></figure>`).join('')})});

if(document.body.dataset.page==='fotos'){
  if('scrollRestoration' in history)history.scrollRestoration='manual';
  const showGalleryTop=()=>window.scrollTo({top:0,left:0,behavior:'auto'});
  window.addEventListener('pageshow',showGalleryTop);
  window.addEventListener('load',showGalleryTop,{once:true});
}

const lightbox=document.querySelector('.photo-lightbox');if(lightbox){const preview=lightbox.querySelector('img');const close=()=>{lightbox.classList.remove('open');lightbox.setAttribute('aria-hidden','true');preview.removeAttribute('src')};document.addEventListener('click',e=>{const trigger=e.target.closest('.photo-open');if(trigger){preview.src=trigger.querySelector('img').src;lightbox.classList.add('open');lightbox.setAttribute('aria-hidden','false')}else if(e.target===lightbox||e.target.closest('.photo-lightbox button'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()})}

const floating=document.querySelector('.floating-actions'),siteFooter=document.querySelector('.site-footer');
if(floating&&siteFooter){let frame;const positionFloating=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{floating.classList.toggle('is-docked',siteFooter.getBoundingClientRect().top<=window.innerHeight-80)})};addEventListener('scroll',positionFloating,{passive:true});addEventListener('resize',positionFloating,{passive:true});addEventListener('load',positionFloating,{once:true});positionFloating()}
